// GENERATED by scripts/sync-setup-check-shared.ts — edit the source under src/, then run `npm run shared:sync`.
/**
 * Drawdown-floor policy — shared by the app (Daily Guard, dashboard, copy
 * trade) and the `setup-validation` Edge Function (synced to _shared).
 *
 * The liquidation threshold is never assumed to be "starting balance − max
 * drawdown". It is known only when:
 *   1. the trader confirmed it (read from a dashboard screenshot, or entered) —
 *      a trailing floor may since have risen with later gains, never fallen;
 *   2. the drawdown is STATIC: threshold = starting balance − allowance;
 *   3. the drawdown TRAILS but the account has never been above its starting
 *      balance: the peak is the start, so threshold = start − allowance.
 * Otherwise a trailing threshold depends on the peak balance / equity, which
 * Prop Guard does not have — the result is "needs verification", never an
 * estimate presented as fact.
 */

export type DrawdownMethod = 'static' | 'trailing' | 'eod_trailing';

export interface ConfirmedThreshold {
  value: number;
  source: 'screenshot' | 'manual';
  /** When it was confirmed (ISO). */
  at: string;
}

export interface FloorInputs {
  method: DrawdownMethod;
  /** False when the drawdown method was never stated (not verified, read or entered). */
  methodKnown: boolean;
  startingBalance: number;
  balance: number;
  highWaterMark: number;
  /** Loss allowance in dollars (already resolved from amount / %), or null when unknown. */
  maxDrawdown: number | null;
  /** A trailing floor stops at starting balance + this offset (0 = at the start); null = never locks. */
  lockOffset: number | null;
  confirmed: ConfirmedThreshold | null;
}

export type FloorBasis = 'confirmed' | 'confirmed_trailed' | 'static_rule' | 'untouched_trailing';
export type FloorNeed = 'threshold' | 'max_drawdown' | 'drawdown_method';

export interface FloorResult {
  floor: number | null;
  basis: FloorBasis | null;
  /** What the trader must provide when the floor is unknown. */
  needs: FloorNeed[];
  /** Plain-language explanation shown next to the number (or instead of it). */
  reason: string;
}

const EPS = 0.005;
const cents = (n: number) => Math.round(n * 100) / 100;
const usd = (n: number) => `$${n.toLocaleString('en-US', { minimumFractionDigits: 0, maximumFractionDigits: 2 })}`;

/** The floor a trailing rule gives for a peak balance (with the lock). */
export function trailingFloor(peak: number, startingBalance: number, maxDrawdown: number, lockOffset: number | null): number {
  const trail = Math.max(peak, startingBalance) - maxDrawdown;
  return cents(lockOffset != null ? Math.min(trail, startingBalance + lockOffset) : trail);
}

export function resolveFloor(i: FloorInputs): FloorResult {
  const dd = i.maxDrawdown != null && i.maxDrawdown > 0 ? i.maxDrawdown : null;
  const trailing = i.method !== 'static';

  if (i.confirmed && Number.isFinite(i.confirmed.value)) {
    const by = i.confirmed.source === 'manual' ? 'entered by you' : 'from your screenshot';
    if (trailing && dd != null && i.methodKnown) {
      // Gains journaled since the confirmation can only raise a trailing floor.
      const fromPeak = trailingFloor(i.highWaterMark, i.startingBalance, dd, i.lockOffset);
      if (fromPeak > i.confirmed.value + EPS)
        return { floor: fromPeak, basis: 'confirmed_trailed', needs: [], reason: `Confirmed threshold ${usd(i.confirmed.value)} (${by}), raised by later gains to ${usd(fromPeak)}.` };
    }
    return { floor: cents(i.confirmed.value), basis: 'confirmed', needs: [], reason: `Liquidation threshold ${by}.` };
  }

  if (dd == null)
    return { floor: null, basis: null, needs: ['threshold'], reason: 'Needs verification — enter the current liquidation threshold from your dashboard (or the max drawdown if your account has a static drawdown).' };
  if (!i.methodKnown)
    return { floor: null, basis: null, needs: ['threshold', 'drawdown_method'], reason: 'Needs verification — the drawdown type (static / trailing) is not confirmed. Enter the current liquidation threshold, or confirm the drawdown type.' };

  if (!trailing) return { floor: cents(i.startingBalance - dd), basis: 'static_rule', needs: [], reason: `Static drawdown: starting balance ${usd(i.startingBalance)} − ${usd(dd)}.` };

  // Trailing: exact only while the account has never been above its start (the peak IS the start).
  if (i.highWaterMark <= i.startingBalance + EPS && i.balance <= i.startingBalance + EPS)
    return { floor: trailingFloor(i.startingBalance, i.startingBalance, dd, i.lockOffset), basis: 'untouched_trailing', needs: [], reason: `Never above the starting balance yet: starting balance ${usd(i.startingBalance)} − ${usd(dd)}.` };

  const kind = i.method === 'eod_trailing' ? 'highest end-of-day balance' : 'highest balance including open profits (intraday)';
  return {
    floor: null,
    basis: null,
    needs: ['threshold'],
    reason: `Needs verification — this drawdown trails your ${kind}, which Prop Guard cannot see. Enter the current liquidation threshold from your dashboard.`,
  };
}
